def count_N(L_max):
    N = {}
    for a in range(-L_max, L_max + 1):
        for b in range(-L_max, L_max + 1):
            if a == 0 and b == 0:
                continue
            m = max(abs(a), abs(b), abs(a+b))
            if m <= L_max:
                N[m] = N.get(m, 0) + 1
    return N

print(count_N(5))
